code.formula:
@Command([EditDocument];"1");

@If (TeamNo= ""; @Return(@Do(@Command([EditGotoField];"TeamNo") ;@Prompt([Ok];"Missing Value"; "Please state the Team number!")));"");
@If (TeamMembers= ""; @Return(@Do(@Command([EditGotoField];"TeamMembers") ;@Prompt([Ok];"Missing Value"; "Please select the Team Members!")));"");
@If (SendTo= ""; @Return(@Do(@Command([EditGotoField];"SendTo") ;@Prompt([Ok];"Missing Value"; "Please select the recipient!")));"");
@If (HOD= ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select the HOD!")));"");
@If (company= ""; @Return(@Do(@Command([EditGotoField];"company") ;@Prompt([Ok];"Missing Value"; "Please select the Company !")));"");
@If (position= ""; @Return(@Do(@Command([EditGotoField];"position") ;@Prompt([Ok];"Missing Value"; "Please insert your Position!")));"");

FIELD Notified := @V3UserName;
FIELD reportedDate :=@Today;
FIELD CurrentAction :="Submitted";

@Command([FileSave]);

@MailSend(SendTo;HOD:TeamMembers:HR:cc;NULL;"Night Visit Notification - Sent for REVIEW: "  +  NVNo ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (rootCause= ""; @Return(@Do(@Command([EditGotoField];"rootCause") ;@Prompt([Ok];"Missing Value"; "Please insert Possible Root Cause before proceeding!")));"");

FIELD acknowledgedDate := @Today;
FIELD CurrentAction :="ReviewDone";

@MailSend(HOD;SendTo:TeamMembers:HR:cc;NULL;"Night Visit Notification - Done Review : "  +  NVNo ;NULL;"Please follow this doclink  -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

