code.formula:
@If(period="IMMEDIATELY"; reportedDate;
period="14 Days"; @Adjust(reportedDate;0;0;14;0;0;0);
period="30 Days"; @Adjust(reportedDate;0;0;30;0;0;0);
period="60 Days"; @Adjust(reportedDate;0;0;60;0;0;0);
period="90 Days"; @Adjust(reportedDate;0;0;90;0;0;0);"")
